inline uint64_t add(issue_t issue) { ensure_preview_issues(); issue.id=s_preview_next_issue++; if(issue.seen_ms==0) issue.seen_ms=aida::preview::network::monotonic_ms(); s_preview_issues.push_back(std::move(issue)); return s_preview_issues.back().id; }
inline bool remove(uint64_t id) { const auto n=s_preview_issues.size(); s_preview_issues.erase(std::remove_if(s_preview_issues.begin(),s_preview_issues.end(),[id](const auto& issue){return issue.id==id;}),s_preview_issues.end()); return n!=s_preview_issues.size(); }
