inline std::vector<issue_t> list(const issue_filter_t& filter) { ensure_preview_issues(); std::vector<issue_t> result; for(const auto& issue:s_preview_issues){if(!filter.include_suppressed&&issue.suppressed)continue;if(filter.has_severity_min&&issue.severity<filter.severity_min)continue;if(filter.has_confidence_min&&issue.confidence<filter.confidence_min)continue;if(filter.has_audit_id&&issue.audit_id!=filter.audit_id)continue;if(!filter.host_substring.empty()&&issue.host.find(filter.host_substring)==std::string::npos)continue;if(!filter.type_key_substring.empty()&&issue.type_key.find(filter.type_key_substring)==std::string::npos)continue;result.push_back(issue);if(filter.limit&&result.size()>=filter.limit)break;} return result; }
