inline size_t count_by_severity(severity_t severity) { ensure_preview_issues(); return static_cast<size_t>(std::count_if(s_preview_issues.begin(),s_preview_issues.end(),[severity](const auto& issue){return issue.severity==severity;})); }
inline nlohmann::json issue_to_json(const issue_t& issue) { return {{"id",issue.id},{"name",issue.name},{"type",issue.type_key},{"severity",severity_label(issue.severity)},{"confidence",confidence_label(issue.confidence)},{"host",issue.host},{"path",issue.path},{"parameter",issue.parameter},{"description",issue.description},{"remediation",issue.remediation},{"cvss_score",issue.cvss_score},{"audit_id",issue.audit_id}}; }
inline nlohmann::json export_json(const issue_filter_t& filter) { auto issues=list(filter); nlohmann::json document={{"count",issues.size()},{"issues",nlohmann::json::array()}}; for(const auto& issue:issues)document["issues"].push_back(issue_to_json(issue)); return document; }
