inline std::vector<uint8_t> encode_frame(const frame_t& frame){std::vector<uint8_t> output(9);const uint32_t length=static_cast<uint32_t>(frame.payload.size());output[0]=static_cast<uint8_t>((length>>16)&0xff);output[1]=static_cast<uint8_t>((length>>8)&0xff);output[2]=static_cast<uint8_t>(length&0xff);output[3]=frame.type;output[4]=frame.flags;uint32_t stream=frame.stream_id&0x7fffffff;if(frame.r_bit)stream|=0x80000000;output[5]=static_cast<uint8_t>((stream>>24)&0xff);output[6]=static_cast<uint8_t>((stream>>16)&0xff);output[7]=static_cast<uint8_t>((stream>>8)&0xff);output[8]=static_cast<uint8_t>(stream&0xff);output.insert(output.end(),frame.payload.begin(),frame.payload.end());return output;}
